import React, { useState, useEffect } from 'react';
import { KeyNode, UpdatePayload } from '../types';

interface FormProps {
  selectedNode: KeyNode | null;
  selectedAdaptation: string;
  onSave: (payload: UpdatePayload) => Promise<void>;
}

export const Form: React.FC<FormProps> = ({ 
  selectedNode, 
  selectedAdaptation, 
  onSave 
}) => {
  const [activeTab, setActiveTab] = useState('en');
  const [formData, setFormData] = useState({
    code: '',
    title: '',
    desc: '',
    purpose: '',
    related_keys: ''
  });
  const [generatedKey, setGeneratedKey] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (selectedNode) {
      setFormData({
        code: selectedNode.code || '',
        title: selectedNode.title || '',
        desc: '',
        purpose: '',
        related_keys: Array.isArray(selectedNode.related_keys) 
          ? selectedNode.related_keys.join(', ') 
          : selectedNode.related_keys || ''
      });
      setGeneratedKey('');
    }
  }, [selectedNode]);

  const generateKey = () => {
    if (!selectedNode || !selectedAdaptation) return;
    
    let key = '';
    if (selectedNode.parent_id === null) {
      // Top level key: Adaptation code + key Code
      key = `${selectedAdaptation}-${formData.code}`;
    } else {
      // Child key: Parent code + key Code
      const parentCode = selectedNode.code || '';
      key = `${parentCode}-${formData.code}`;
    }
    
    setGeneratedKey(key);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!generatedKey) {
      alert('Please generate a key first');
      return;
    }

    setIsSaving(true);
    try {
      const payload: UpdatePayload = {
        key: generatedKey,
        lang: activeTab,
        code: formData.code,
        title: formData.title,
        desc: formData.desc,
        purpose: formData.purpose,
        related_keys: formData.related_keys
      };
      
      await onSave(payload);
    } catch (error) {
      console.error('Error saving:', error);
    } finally {
      setIsSaving(false);
    }
  };

  if (!selectedNode) {
    return (
      <div className="form-placeholder">
        <p>Select a node from the tree view to edit</p>
      </div>
    );
  }

  return (
    <div className="form-container">
      <div className="form-tabs">
        <button
          type="button"
          className={`tab ${activeTab === 'en' ? 'active' : ''}`}
          onClick={() => setActiveTab('en')}
        >
          English
        </button>
        <button
          type="button"
          className={`tab ${activeTab === 'es' ? 'active' : ''}`}
          onClick={() => setActiveTab('es')}
        >
          Spanish
        </button>
        <button
          type="button"
          className={`tab ${activeTab === 'fr' ? 'active' : ''}`}
          onClick={() => setActiveTab('fr')}
        >
          French
        </button>
      </div>

      <form onSubmit={handleSubmit} className="form">
        <div className="form-group">
          <label htmlFor="code">Field Code (10)</label>
          <input
            type="text"
            id="code"
            value={formData.code}
            onChange={(e) => setFormData({ ...formData, code: e.target.value })}
            maxLength={10}
            required
            className="form-input"
          />
        </div>

        <div className="form-group">
          <label htmlFor="title">Title</label>
          <input
            type="text"
            id="title"
            value={formData.title}
            onChange={(e) => setFormData({ ...formData, title: e.target.value })}
            required
            className="form-input"
          />
        </div>

        <div className="form-group">
          <label htmlFor="desc">Description (HTML) *</label>
          <textarea
            id="desc"
            value={formData.desc}
            onChange={(e) => setFormData({ ...formData, desc: e.target.value })}
            required
            rows={4}
            className="form-textarea"
            placeholder="Enter HTML description..."
          />
        </div>

        <div className="form-group">
          <label htmlFor="purpose">Purpose (HTML)</label>
          <textarea
            id="purpose"
            value={formData.purpose}
            onChange={(e) => setFormData({ ...formData, purpose: e.target.value })}
            rows={4}
            className="form-textarea"
            placeholder="Enter HTML purpose (optional)..."
          />
        </div>

        <div className="form-group">
          <label htmlFor="related_keys">Related Keys</label>
          <input
            type="text"
            id="related_keys"
            value={formData.related_keys}
            onChange={(e) => setFormData({ ...formData, related_keys: e.target.value })}
            className="form-input"
            placeholder="Enter related keys..."
          />
        </div>

        <div className="form-actions">
          <button
            type="button"
            onClick={generateKey}
            className="btn btn-secondary"
          >
            Save Key
          </button>
          
          {generatedKey && (
            <div className="generated-key">
              <strong>Generated Key:</strong> {generatedKey}
            </div>
          )}
        </div>

        <button
          type="submit"
          disabled={isSaving || !generatedKey}
          className="btn btn-primary"
        >
          {isSaving ? 'Saving...' : 'Save Data'}
        </button>
      </form>
    </div>
  );
};
