import React from 'react';
import { KeyNode } from '../types';

interface TreeViewProps {
  nodes: KeyNode[];
  onNodeSelect: (node: KeyNode) => void;
  selectedNode?: KeyNode;
}

const TreeViewItem: React.FC<{
  node: KeyNode;
  level: number;
  onNodeSelect: (node: KeyNode) => void;
  selectedNode?: KeyNode;
}> = ({ node, level, onNodeSelect, selectedNode }) => {
  const isSelected = selectedNode?.id === node.id;
  
  return (
    <div className="tree-item">
      <div 
        className={`tree-node ${isSelected ? 'selected' : ''}`}
        style={{ paddingLeft: `${level * 20}px` }}
        onClick={() => onNodeSelect(node)}
      >
        <span className="tree-icon">
          {node.children.length > 0 ? '📁' : '📄'}
        </span>
        <span className="tree-label">{node.title}</span>
        <span className="tree-code">({node.code})</span>
      </div>
      {node.children.length > 0 && (
        <div className="tree-children">
          {node.children.map((child) => (
            <TreeViewItem
              key={child.id}
              node={child}
              level={level + 1}
              onNodeSelect={onNodeSelect}
              selectedNode={selectedNode}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export const TreeView: React.FC<TreeViewProps> = ({ 
  nodes, 
  onNodeSelect, 
  selectedNode 
}) => {
  return (
    <div className="tree-view">
      <h3 className="tree-title">Keys Structure</h3>
      <div className="tree-container">
        {nodes.map((node) => (
          <TreeViewItem
            key={node.id}
            node={node}
            level={0}
            onNodeSelect={onNodeSelect}
            selectedNode={selectedNode}
          />
        ))}
      </div>
    </div>
  );
};
